import { defineConfig, mergeConfig } from './mfl/node_modules/vite/dist/node/index.js';
import original from './mfl/vite.config.ts';
export default mergeConfig(original, defineConfig({ plugins: [{
  name: 'pr178-research-policy-B', enforce: 'pre',
  transform(code, id) {
    if (!id.replaceAll('\\','/').endsWith('/matchSimulation/decisionPolicyConfig.ts')) return;
    const before = "export const DEFAULT_DECISION_POLICY: DecisionPolicyId = 'legacy-pr176';";
    if (!code.includes(before)) throw new Error('Research default override contract changed');
    return code.replace(before, "export const DEFAULT_DECISION_POLICY: DecisionPolicyId = 'state-value-v1';");
  },
}], server: { host:'127.0.0.1',port:5178,strictPort:true } }));
